mapper.select:
SELECT f.id AS feedback_id, f.user_id, u.nick_name AS nickname, AS phone_masked, f.category, f.content, f.status, f.reply, h.nick_name AS handler_name, f.create_time AS submitted_at, f.handled_at FROM user_feedback f JOIN sys_user u ON u.user_id = f.user_id LEFT JOIN sys_user h ON h.user_id = f.handler_id WHERE 1 = 1
AND f.status = #{status}
AND f.category = #{category}
AND ( f.content LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') )
AND f.create_time >= #{beginTime}
AND f.create_time <= #{endTime}
ORDER BY ${orderByColumn} ${isAsc}

