UPDATE user_feedback f
SET f.status = 'REPLIED',
    f.reply = #{reply},
    f.handler_id = #{handlerId},
    f.handled_at = NOW(),
    f.update_time = NOW()
WHERE f.id = #{feedbackId}
  AND f.status = #{expectedStatus}
  AND f.status IN

